    const sigOf = (await import('/src/cad/refs.js')).faceSignature;
    cap.features.push(F.createFeature(cap, 'connectionPoint', { face: sigOf(bottom), cpName: 'Plug' }));
    m.actions.change('op.edit', () => {});
    m.actions.cancelEditing?.({ quiet: true });
    m.project.assemblies.push({ id: 'asmM', name: 'Asm', components: [], mates: [] });
    await m.actions.switchDocument({ kind: 'assembly', id: 'asmM' });
    m.actions.cancelEditing?.({ quiet: true });
    m.actions.insertComponent(base.id); m.actions.insertComponent(cap.id);
    const a = m.active();
    const [cb, cc] = a.components;
    m.actions.change('op.edit', () => { cb.fixed = true; cb.position = [0, 0, 0]; cc.fixed = false; cc.position = [200, 0, 40]; cc.rotation = [0, 0, 0, 1]; });
    await sleep(200);
    const far = m.commands.magneticSnap.run() ?? 0;
    const farMates = a.mates.length;
    m.actions.change('op.edit', () => { cc.position = [3, 4, 18]; });
    await sleep(200);
