    const mg = a.mates.filter((x) => x.type === 'magnetic');
    const A = await import('/src/cad/assembly.js');
    const c1 = m.active().components[1];
    const p = A.placePoint(c1, [10, 10, 0]).map((v) => v.toFixed(2)).join(',') + ' ' + A.placeDir(c1, [0, 0, 1])[2].toFixed(3);
    return [pmOk, Boolean(cpf), farMates, mg.length, mg[0]?.a.conn, mg[0]?.b.conn, p, m.state.failedMates.size].join(' ');
  })()
